theorem chernoff_tail [IsProbabilityMeasure μ] {X : Ω → ℝ} {c : ℝ≥0}
    (hSubG : HasSubgaussianMGF X c μ) {t : ℝ} (ht : 0 ≤ t) :
    μ.real {ω | t ≤ |X ω|} ≤ 2 * Real.exp (-t ^ 2 / (2 * (c : ℝ)))

theorem subGaussianMGF_tail_twoSided [IsProbabilityMeasure μ] {X : Ω → ℝ} {c : ℝ≥0}
    (hSubG : HasSubgaussianMGF (fun ω => X ω - μ[X]) c μ) {t : ℝ} (ht : 0 ≤ t) :
    μ.real {ω | t ≤ |X ω - μ[X]|} ≤ 2 * Real.exp (-t ^ 2 / (2 * (c : ℝ)))

theorem diagonalGaussianDensity_nonneg {d : ℕ}
    (params : DiagonalGaussianParams d) (x : GaussianParameterSpace d) :
    0 ≤ diagonalGaussianDensity params x

theorem subGaussianFiniteSumTailBound
    {Ω ι : Type*} [MeasurableSpace Ω] {μ : Measure Ω}
    {X : ι → Ω → ℝ} (hIndep : iIndepFun X μ) {c : ι → ℝ≥0}
    {s : Finset ι} (hSubG : ∀ i ∈ s, HasSubgaussianMGF (X i) (c i) μ)
    {ε : ℝ} (hε : 0 ≤ ε) :
    μ.real {ω | ε ≤ ∑ i ∈ s, X i ω}
      ≤ Real.exp (-ε ^ 2 / (2 * ∑ i ∈ s, c i))

theorem subGaussianMGFImpliesRightTailBound
    {Ω : Type*} [MeasurableSpace Ω] {μ : Measure Ω}
    {X : Ω → ℝ} {σ : ℝ≥0} {t : ℝ}
    (hSubG : HasSubgaussianMGF X (σ ^ 2) μ)
    (ht : 0 ≤ t) :
    μ.real {ω | t ≤ X ω} ≤ Real.exp (-t ^ 2 / (2 * (σ : ℝ) ^ 2))

theorem epsilonRepresentativeERMWorks
    {H : Type*} {risk empiricalRisk : H → ℝ} {ε : ℝ}
    {hERM hComparator : H}
    (hRepresentative : ∀ h, |risk h - empiricalRisk h| ≤ ε)
    (hERMmin : ∀ h, empiricalRisk hERM ≤ empiricalRisk h) :
    risk hERM ≤ risk hComparator + 2 * ε

theorem finiteTimeClassTwoSidedUniformDeviationUnionBound_cardInv
    {Ω Time H : Type*} [MeasurableSpace Ω] {μ : Measure Ω}
    [Fintype Time] [Nonempty Time] [Fintype H] [Nonempty H]
    (deviation : Time → H → Ω → ℝ) {ε : ℝ} {δ : ℝ≥0∞}
    (hPointwiseTail :
      ∀ t h, μ {ω | ε ≤ |deviation t h ω|}
        ≤ δ * (Fintype.card (Time × H) : ℝ≥0∞)⁻¹) :
    μ (⋃ p : Time × H, {ω | ε ≤ |deviation p.1 p.2 ω|}) ≤ δ

theorem finiteTimeClassTwoSidedUniformDeviationUnionBound_timeBudget
    {Ω Time H : Type*} [MeasurableSpace Ω] {μ : Measure Ω}
    [Fintype Time] [Fintype H] [Nonempty H]
    (deviation : Time → H → Ω → ℝ) (timeBudget : Time → ℝ≥0∞)
    {ε : ℝ} {δ : ℝ≥0∞}
    (hBudgetSum : ∑ t, timeBudget t ≤ δ)
    (hPointwiseTail :
      ∀ t h, μ {ω | ε ≤ |deviation t h ω|}
        ≤ timeBudget t * (Fintype.card H : ℝ≥0∞)⁻¹) :
    μ (⋃ p : Time × H, {ω | ε ≤ |deviation p.1 p.2 ω|}) ≤ δ

theorem linearityOfExpectationIntegrable
    {Ω : Type*} [MeasurableSpace Ω] {μ : Measure Ω}
    {X Y : Ω → ℝ} {a b : ℝ}
    (hX : Integrable X μ) (hY : Integrable Y μ) :
    (∫ ω, (a * X ω + b * Y ω) ∂μ) =
      a * (∫ ω, X ω ∂μ) + b * (∫ ω, Y ω ∂μ)

theorem condExp_sq_eq_condVar_of_centered
    {Ω : Type*} {m₀ : MeasurableSpace Ω}
    {μ : Measure Ω} [IsProbabilityMeasure μ]
    {m : MeasurableSpace Ω}
    {X : Ω → ℝ}
    (_hX_meas : Measurable X)
    (_hX_sq_int : Integrable (fun ω => X ω ^ 2) μ)
    (hcenter : μ[X | m] =ᵐ[μ] 0) :
    μ[fun ω => (X ω - (μ[X | m]) ω) ^ 2 | m] =ᵐ[μ] μ[fun ω => X ω ^ 2 | m]

theorem bettingWealth_nonneg {Ω : Type*} {X lambda : ℕ → Ω → ℝ} {m : ℝ}
    (hfactor_nonneg : ∀ k ω, 0 ≤ bettingFactor X lambda m k ω) :
    0 ≤ bettingWealthProcess X lambda m
